function sectionEligibilityChanged(section){const eligible=sectionQuestions(section).map(question=>question.id);section.question_ids=section.question_ids.filter(id=>eligible.includes(id));if(form.value.question_selection==='manual')section.question_count=section.question_ids.length}
function packageTypeChanged(){if(form.value.test_type!=='certification')form.value.certificate_enabled=false;form.value.sections.forEach(section=>{section.question_ids=section.question_ids.filter(id=>questionPool.value.some(question=>question.id===id&&questionEligible(question)));if(form.value.question_selection==='manual')section.question_count=section.question_ids.length})}
