async function load(){loading.value=true;error.value='';try{if(resource==='settings'){references();const result=await api('/admin/settings');settings.value=result.settings||result;await loadPolicies()}else{const query=new URLSearchParams({page:page.value,search:search.value});if(filterType.value)query.set('type',filterType.value);if(filterCompetency.value)query.set('competency_id',filterCompetency.value);if(filterStatus.value)query.set('status',filterStatus.value);if(filterTestType.value)query.set('test_type',filterTestType.value);const response=await api('/admin/'+resource+'?'+query);rows.value=list(response);total.value=response.total??rows.value.length;lastPage.value=response.last_page||1}}catch(e){error.value=e.message}finally{loading.value=false}}
