async function open(row=null){clearValidation('editor');error.value='';form.value=blank();if(row){try{form.value={...form.value,...await api('/admin/'+resource+'/'+row.id)}}catch(e){notify(e.message,true);return}}if(resource==='questions'){form.value.allowed_test_types=form.value.allowed_test_types||[...testTypeCodes];form.value.metadata={rubric:[],matches:[],...form.value.metadata};form.value.answer_schema={accepted:[],...form.value.answer_schema};form.value.metadata.rubric=normalizeRubric(form.value.metadata.rubric);form.value.accepted_text=(form.value.answer_schema.accepted||[]).join('\n');if(!Array.isArray(form.value.metadata.matches))form.value.metadata.matches=[];if(['matching','drag_drop'].includes(form.value.type)){form.value.metadata.left_items=form.value.metadata.left_items||form.value.options.map(o=>({...o}));form.value.metadata.right_items=form.value.metadata.right_items||form.value.metadata.matches||[];form.value.options=form.value.metadata.left_items.map(o=>({...o,match_id:form.value.answer_schema.correct?.[o.id]||''}));form.value.metadata.matches=form.value.metadata.right_items}}if(resource==='packages'){form.value.test_type=form.value.test_type||'certification';form.value.settings={lock_sections:true,randomize_options:true,...form.value.settings};setupPackagePolicy();form.value.sections=(form.value.sections||[]).map(s=>({...s,question_ids:s.question_ids||[],difficulties:s.difficulties||[]}));loadPolicies()}if(resource==='questions')form.value.metadata.blanks=(form.value.metadata.blanks||[]).map(b=>({...b,correct:form.value.answer_schema.correct?.[b.id]||''}));if(resource==='participants'){form.value.profile={...form.value.profile};if(form.value.activation_pending||form.value.account_status==='pending_activation')form.value.active=true;}modal.value=true;if(['questions','groups','packages'].includes(resource))references()}
function buildQuestion(){const value=JSON.parse(JSON.stringify(form.value));if(value.usage_limit==='')value.usage_limit=null;if(['short_answer','fill_blank'].includes(value.type)){value.answer_schema.accepted=String(value.accepted_text||'').split('\n').map(s=>s.trim()).filter(Boolean);if(!value.answer_schema.correct)value.answer_schema.correct=value.answer_schema.accepted[0]||''}if(isOrdering.value)value.answer_schema.correct=value.options.map(o=>o.id);if(['matching','drag_drop'].includes(value.type)){value.answer_schema.correct=Object.fromEntries(value.options.map(o=>[o.id,o.match_id||'']));value.metadata.left_items=value.options.map(({id,text})=>({id,text}));value.metadata.right_items=value.metadata.matches.map(({id,text})=>({id,text}));value.options=value.metadata.right_items}if(['essay','speaking'].includes(value.type))value.metadata.manual=true;if(['dropdown','fill_blank'].includes(value.type)&&Array.isArray(value.metadata.blanks)&&value.metadata.blanks.length){value.answer_schema.correct=Object.fromEntries(value.metadata.blanks.map(b=>[b.id,b.correct||'']));value.metadata.blanks=value.metadata.blanks.map(({id,label,options})=>({id,label,options}))}if(['essay','speaking','short_answer','fill_blank','true_false'].includes(value.type)||(value.type==='dropdown'&&value.metadata.blanks?.length))value.options=[];return value}
async function save(){clearValidation('editor');busy.value=true;error.value='';try{let body=resource==='questions'?buildQuestion():JSON.parse(JSON.stringify(form.value));const resourceId=body.id;if(resource==='participants'){body=Object.fromEntries(Object.entries(body).filter(([key])=>['name','email','password','active','profile'].includes(key)));if(!body.password)delete body.password;}if(resource==='packages'){body.policy_overrides=Object.fromEntries(Object.entries(body.policy_overrides||{}).filter(([,value])=>value!==null&&value!==''));if(body.test_type!=='certification')body.certificate_enabled=false;body.sections.forEach((s,i)=>{s.position=i;if(body.question_selection==='manual')s.question_count=s.question_ids.length||s.question_count})}await api('/admin/'+resource+(resourceId?'/'+resourceId:''),{method:resourceId?'PUT':'POST',body});modal.value=false;notify(t('saveSuccess'));await load();if(['competencies','packages','levels'].includes(resource))bootstrap()}catch(e){error.value=e.message;await showValidation('editor',e,'[data-dialog=editor]')}finally{busy.value=false}}
