async function archive(row){const message=resource==='groups'?(state.language==='id'?'Hapus permanen grup yang tidak digunakan ini? Isi grup akan dihapus.':'Permanently delete this unused group? Its content will be removed.'):t('confirmArchive');if(!confirm(message))return;try{await api('/admin/'+resource+'/'+row.id,{method:'DELETE'});notify(t('saveSuccess'));load()}catch(e){notify(e.message,true)}}
async function duplicate(row){try{await api('/admin/questions/'+row.id+'/duplicate',{method:'POST'});notify('Question duplicated as a draft.');load()}catch(e){notify(e.message,true)}}
function addBlank(){form.value.metadata.blanks=form.value.metadata.blanks||[];form.value.metadata.blanks.push({id:'b'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),label:'Blank '+(form.value.metadata.blanks.length+1),correct:'',options:[{id:'a',text:''},{id:'b',text:''}]})}
function addOption(){const id='opt_'+Date.now().toString(36);form.value.options.push({id,text:''})}
function setCorrect(id){const schema=form.value.answer_schema;if(form.value.type==='multiple_response'){if(!Array.isArray(schema.correct))schema.correct=[];const i=schema.correct.indexOf(id);if(i<0)schema.correct.push(id);else schema.correct.splice(i,1)}else schema.correct=id}
function isCorrect(id){return Array.isArray(form.value.answer_schema.correct)?form.value.answer_schema.correct.includes(id):form.value.answer_schema.correct===id}
function typeChange(){form.value.metadata.manual=['essay','speaking'].includes(form.value.type);if(['matching','drag_drop'].includes(form.value.type)){form.value.metadata.matches=form.value.metadata.matches?.length?form.value.metadata.matches:[{id:'r1',text:''},{id:'r2',text:''}]}form.value.answer_schema.correct=form.value.type==='multiple_response'?[]:form.value.type==='true_false'?'true':['essay','speaking','short_answer','fill_blank'].includes(form.value.type)?'':form.value.options?.[0]?.id||''}
function addSection(){form.value.sections.push({title:'New section',competency_id:state.competencies[0]?.id||'',duration_minutes:10,weight:1,question_count:5,question_ids:[],difficulties:[],randomize:true})}
function moveSection(i,d){const next=i+d;if(next<0||next>=form.value.sections.length)return;const arr=form.value.sections;[arr[i],arr[next]]=[arr[next],arr[i]]}let dragIndex=null;function dropSection(i){if(dragIndex===null)return;const s=form.value.sections.splice(dragIndex,1)[0];form.value.sections.splice(i,0,s);dragIndex=null}
function selectQuestion(section,id){const i=section.question_ids.indexOf(id);if(i<0)section.question_ids.push(id);else section.question_ids.splice(i,1);section.question_count=section.question_ids.length}
async function upload(event,isImport=false){const file=event.target.files?.[0];if(!file)return;busy.value=true;try{const body=new FormData();body.append('file',file);const result=await api(isImport?'/admin/questions/import':'/admin/media',{method:'POST',body});if(isImport)importReport.value=result;notify(isImport?'Import completed. Review the import report.':'File uploaded successfully.');await load()}catch(e){notify(e.message,true)}finally{busy.value=false;event.target.value=''}}
async function saveSettings(){clearValidation('settings');busy.value=true;try{await api('/admin/settings',{method:'PUT',body:settings.value});notify(t('saveSuccess'));bootstrap()}catch(e){notify(e.message,true);await showValidation('settings',e,'.settings-form')}finally{busy.value=false}}
function openReview(row){clearValidation('review');review.value=row;reviewForm.value={score:row.manual_score??row.score??0,feedback:row.feedback||'',scores:{}}}
const reviewRubric=computed(()=>normalizeRubric(review.value?.question?.metadata?.rubric));
const weightedReviewScore=computed(()=>{let total=0,weights=0;for(const [i,criterion] of reviewRubric.value.entries()){const score=reviewForm.value.scores[criterion.name||i];if(score===undefined||score==='')return null;const weight=Number(criterion.weight)||1;total+=Number(score)*weight;weights+=weight}return weights?Math.round(total/weights*100)/100:null});
watch(weightedReviewScore,score=>{if(score!==null)reviewForm.value.score=score});
async function submitReview(){clearValidation('review');busy.value=true;try{const body={...reviewForm.value};if(reviewRubric.value.length&&weightedReviewScore.value!==null)body.score=weightedReviewScore.value;await api('/admin/reviews/'+review.value.id,{method:'POST',body});review.value=null;notify(t('saveSuccess'));load()}catch(e){notify(e.message,true);await showValidation('review',e,'[data-dialog=review]')}finally{busy.value=false}}
