let searchTimer;watch(search,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;load()},350)});watch([filterType,filterCompetency,filterStatus,filterTestType],()=>{page.value=1;load()});
const previewQuestion=computed(()=>resource==='questions'?buildQuestion():{});
function showPreview(){previewResponse.value=null;preview.value=true}
const adminWorkspace=ref(null);
const validation=ref({editor:{},settings:{},policy:{},review:{}}),validationMessages=ref({editor:'',settings:'',policy:'',review:''});
let validationMessageId=0;
function clearValidation(scope){validation.value[scope]={};validationMessages.value[scope]=''}
function renderFieldError(element,binding){
    const {errors={},field}=binding.value||{};
    if(!field)return;
    if(element.matches('input,select,textarea')&&!element.hasAttribute('name'))element.setAttribute('name',field);
    const messages=errors[field],message=Array.isArray(messages)?messages.join(' '):messages||'';
    let detail=element.__inbafFieldError;
    if(message){
        if(!detail){
            const node=document.createElement('p');node.className='admin-field-error';node.id='admin-field-error-'+(++validationMessageId);node.setAttribute('role','alert');
            detail={node,describedBy:element.getAttribute('aria-describedby'),ariaLabel:element.getAttribute('aria-label')};element.__inbafFieldError=detail;
            const textbox=element.querySelector('[contenteditable="true"]');
            if(textbox)Object.assign(detail,{textbox,textboxDescribedBy:textbox.getAttribute('aria-describedby'),textboxInvalid:textbox.getAttribute('aria-invalid')});
            // An error inside a wrapping label must not become part of the control's name.
            const label=element.closest('label');
            if(label&&!detail.ariaLabel){const copy=label.cloneNode(true);copy.querySelectorAll('input,select,textarea,button,.rich-editor,.admin-field-error').forEach(child=>child.remove());const name=copy.textContent.replace(/\s+/g,' ').trim();if(name)element.setAttribute('aria-label',name)}
            element.insertAdjacentElement('afterend',node);
        }
        detail.node.textContent=message;
        element.setAttribute('aria-invalid','true');
        element.setAttribute('aria-describedby',[detail.describedBy,detail.node.id].filter(Boolean).join(' '));
        if(detail.textbox){detail.textbox.setAttribute('aria-invalid','true');detail.textbox.setAttribute('aria-describedby',[detail.textboxDescribedBy,detail.node.id].filter(Boolean).join(' '))}
    }else if(detail){
        detail.node.remove();element.removeAttribute('aria-invalid');
        if(detail.describedBy)element.setAttribute('aria-describedby',detail.describedBy);else element.removeAttribute('aria-describedby');
        if(detail.ariaLabel)element.setAttribute('aria-label',detail.ariaLabel);else element.removeAttribute('aria-label');
        if(detail.textbox){if(detail.textboxDescribedBy)detail.textbox.setAttribute('aria-describedby',detail.textboxDescribedBy);else detail.textbox.removeAttribute('aria-describedby');if(detail.textboxInvalid!==null)detail.textbox.setAttribute('aria-invalid',detail.textboxInvalid);else detail.textbox.removeAttribute('aria-invalid')}
        delete element.__inbafFieldError;
    }
}
const vFieldError={mounted:renderFieldError,updated:renderFieldError,beforeUnmount(element){element.__inbafFieldError?.node.remove()}};
async function showValidation(scope,failure,selector){
    validation.value[scope]=failure.data?.errors||{};validationMessages.value[scope]=failure.message;
    await nextTick();
    const invalid=adminWorkspace.value?.querySelector(selector)?.querySelector('[aria-invalid="true"]');
    const control=invalid?.matches('input,select,textarea,button')?invalid:invalid?.querySelector('[contenteditable="true"]')||invalid?.querySelector('input,select,textarea,button');
    if(control){control.focus({preventScroll:true});control.scrollIntoView({block:'center',behavior:'instant'})}
}
