const hasFilters=computed(()=>Boolean(search.value||filterType.value||filterCompetency.value||filterStatus.value||filterTestType.value));
const activeDialog=computed(()=>preview.value?'preview':usageQuestion.value?'usage':detail.value?'detail':review.value?'review':modal.value?'editor':null);
const ui=(en,id)=>state.language==='id'?id:en;
const emptyDescription=computed(()=>hasFilters.value?ui('Try a different search or clear the filters to see more records.','Coba kata pencarian lain atau hapus filter untuk menampilkan data lainnya.'):({questions:ui('Create a question or import your question bank to get started.','Buat soal atau impor bank soal Anda untuk memulai.'),packages:ui('Create an assessment and add sections for the skills you want to measure.','Buat paket ujian dan tambahkan bagian untuk kompetensi yang ingin dinilai.'),participants:ui('Participant accounts will appear here after registration or creation.','Akun peserta akan tampil di sini setelah registrasi atau ditambahkan.'),reviews:ui('Written and recorded responses awaiting review will appear here.','Jawaban tertulis dan rekaman yang menunggu penilaian akan tampil di sini.'),certificates:ui('Issued certificates will appear here after eligible assessments are completed.','Sertifikat yang diterbitkan akan tampil di sini setelah ujian yang memenuhi syarat selesai.'),audit:ui('Platform activity will appear here as people use INBAF.','Aktivitas platform akan tampil di sini saat INBAF digunakan.'),media:ui('Upload an image, audio recording, or video to use in your assessments.','Unggah gambar, rekaman audio, atau video untuk digunakan dalam ujian.')}[resource]||ui('Add your first record using the action above.','Tambahkan data pertama melalui tombol di atas.')));
function clearFilters(){search.value='';filterType.value='';filterCompetency.value='';filterStatus.value='';filterTestType.value=''}
function closeActiveDialog(){if(preview.value)preview.value=false;else if(usageQuestion.value)usageQuestion.value=null;else if(detail.value)detail.value=null;else if(review.value)review.value=null;else modal.value=false}
const dialogReturnTargets=new Map();
function isDialogOpen(name){return Boolean({editor:modal.value,preview:preview.value,usage:usageQuestion.value,review:review.value,detail:detail.value}[name])}
// Each dialog owns focus while open, including a preview opened above the editor.
watch(activeDialog,async(name,previous,onCleanup)=>{
    if(typeof document==='undefined')return;
    const returnFocus=previous&&!isDialogOpen(previous)?dialogReturnTargets.get(previous):null;
    if(previous&&!isDialogOpen(previous))dialogReturnTargets.delete(previous);
    if(!name){await nextTick();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});return}
    if(!dialogReturnTargets.has(name))dialogReturnTargets.set(name,document.activeElement);
    const previousOverflow=document.body.style.overflow;
    let disposed=false;
    let dialog=null;
    const focusable=()=>dialog?[...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]):not([type="hidden"]),select:not([disabled]),textarea:not([disabled]),[contenteditable="true"],[tabindex]:not([tabindex="-1"])')].filter(element=>!element.hidden&&element.getClientRects().length>0):[];
    function handleKey(event){
        if(event.key==='Escape'){event.preventDefault();event.stopPropagation();closeActiveDialog();return}
        if(event.key!=='Tab'||!dialog)return;
        const items=focusable(),first=items[0],last=items.at(-1);
        if(!first){event.preventDefault();dialog.focus();return}
        if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last.focus()}
        else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first.focus()}
    }
    onCleanup(()=>{disposed=true;document.removeEventListener('keydown',handleKey,true);document.body.style.overflow=previousOverflow});
    document.body.style.overflow='hidden';
    await nextTick();
    if(disposed)return;
    dialog=adminWorkspace.value?.querySelector(`[data-dialog="${name}"]`);
    if(!dialog)return;
    document.addEventListener('keydown',handleKey,true);
    (returnFocus?.isConnected&&dialog.contains(returnFocus)?returnFocus:focusable()[0]||dialog).focus({preventScroll:true});
});
onMounted(load);
</script>
<template>
<div ref="adminWorkspace" class="admin-workspace">
<div class="admin-content" :inert="activeDialog?true:undefined" :aria-busy="loading">
<div class="page-heading"><div><div class="eyebrow"><span></span>ASSESSMENT WORKSPACE</div><h1>{{t(resource)}}</h1><p>{{description[resource]}}</p></div><div class="heading-actions"><button v-if="resource==='packages'" class="button secondary" @click="go('/admin/settings?tab=test-types')"><Icon name="Settings2" :size="17"/>{{t('policySettings')}}</button><template v-if="resource==='questions'"><a class="button secondary" href="/api/admin/questions/export"><Icon name="Download" :size="17"/>{{t('export')}}</a><button class="button secondary" @click="importInput.click()" :disabled="busy"><Icon name="Upload" :size="17"/>{{t('import')}}</button><a class="button secondary" href="/api/admin/questions/template?format=xlsx" title="Download XLSX import template"><Icon name="FileSpreadsheet" :size="17"/>Template</a><input ref="importInput" hidden type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" @change="upload($event,true)"></template><button v-if="resource==='media'" class="button" @click="fileInput.click()" :disabled="busy"><Icon name="Upload" :size="17"/>{{t('upload')}}</button><input ref="fileInput" hidden type="file" accept="image/*,audio/*,video/*" @change="upload($event)"><button v-if="!isReadOnly&&resource!=='media'&&resource!=='settings'" class="button" @click="open()"><Icon name="Plus" :size="18"/>{{t('create')}}</button></div></div>
<div v-if="error&&!modal" class="inline-error" role="alert"><span>{{error}}</span><button class="text-button" type="button" @click="load">{{t('retryLoad')}}</button></div><div v-if="importReport" class="notice-banner"><Icon name="FileCheck2"/><div>Import: {{importReport.count??importReport.imported??importReport.created??0}} questions added.<p v-if="importReport.errors?.length">{{importReport.errors.map(e=>typeof e==='string'?e:JSON.stringify(e)).join(' · ')}}</p><a href="/api/admin/questions/template" class="text-button">{{t('template')}}</a></div><button class="icon-button" @click="importReport=null" aria-label="Dismiss"><Icon name="X" :size="18"/></button></div>
<template v-if="resource==='settings'"><div class="settings-layout"><nav class="panel settings-nav" :aria-label="ui('Settings sections','Bagian pengaturan')"><button v-for="tab in allTabs" :key="tab" :class="{selected:settingTab===tab}" :aria-current="settingTab===tab?'page':undefined" @click="settingTab=tab"><Icon :name="{Identity:'Building2',Branding:'Palette',Assessment:'ClipboardList',Certificates:'BadgeCheck',Security:'ShieldCheck',Notifications:'Bell',Other:'SlidersHorizontal'}[tab]" :size="18"/>{{tab}}<Icon name="ChevronRight" :size="15"/></button><button :class="{selected:settingTab==='TestTypes'}" :aria-current="settingTab==='TestTypes'?'page':undefined" @click="settingTab='TestTypes'"><Icon name="Layers" :size="18"/>{{t('testTypes')}}<Icon name="ChevronRight" :size="15"/></button><button @click="go('/admin/levels')"><Icon name="ChartNoAxesColumnIncreasing" :size="18"/>Proficiency thresholds<Icon name="ArrowUpRight" :size="15"/></button></nav><form v-if="settingTab!=='TestTypes'" class="panel settings-form" :aria-busy="busy" @submit.prevent="saveSettings"><div class="panel-heading"><div><h3>{{settingTab}} settings</h3><p>Changes apply to new assessments and future platform activity.</p></div><Icon name="SlidersHorizontal" class="muted"/></div><div v-if="validationMessages.settings" class="inline-error" role="alert">{{validationMessages.settings}}</div><div v-if="loading" class="loading-panel">{{t('loading')}}</div><div v-else class="form-grid"><label v-for="key in currentSettings" :key="key" :class="{span2:['footer','institution_address','tagline'].includes(key),'toggle-field':boolSetting(key)}"><template v-if="boolSetting(key)"><span>{{human(key)}}</span><input type="checkbox" v-model="settings[key]" class="toggle" v-field-error="{errors:validation.settings,field:key}"></template><template v-else>{{human(key)}}<select v-if="key==='default_locale'" v-model="settings[key]" v-field-error="{errors:validation.settings,field:key}"><option value="en">English</option><option value="id">Bahasa Indonesia</option></select><select v-else-if="key==='certificate_template'" v-model="settings[key]" v-field-error="{errors:validation.settings,field:key}"><option value="modern">Modern</option><option value="formal">Formal</option></select><select v-else-if="key==='session_policy'" v-model="settings[key]" v-field-error="{errors:validation.settings,field:key}"><option value="sequential">Sequential sections</option><option value="flexible">Flexible sections</option></select><select v-else-if="key==='certificate_paper'" v-model="settings[key]" v-field-error="{errors:validation.settings,field:key}"><option value="a4">A4</option><option value="letter">US Letter</option></select><select v-else-if="key==='certificate_orientation'" v-model="settings[key]" v-field-error="{errors:validation.settings,field:key}"><option value="landscape">Landscape</option><option value="portrait">Portrait</option></select><select v-else-if="key==='storage_driver'" v-model="settings[key]" v-field-error="{errors:validation.settings,field:key}"><option value="local">Protected local storage</option></select><select v-else-if="key.endsWith('_media_id')" v-model="settings[key]" v-field-error="{errors:validation.settings,field:key}"><option :value="null">Default / none</option><option v-for="asset in media.filter(m=>m.kind==='image')" :key="asset.id" :value="asset.id">{{asset.original_name}}</option></select><textarea v-else-if="['footer','institution_address'].includes(key)" v-model="settings[key]" rows="3" v-field-error="{errors:validation.settings,field:key}"></textarea><input v-else :type="key==='primary_color'?'color':numberSetting(key)?'number':'text'" v-model.number="settings[key]" :min="numberSetting(key)?0:undefined" v-field-error="{errors:validation.settings,field:key}"></template></label></div><div class="form-footer"><button class="button" :disabled="busy"><Icon name="Check" :size="17"/>{{t('save')}}</button></div></form><form v-else class="panel settings-form test-type-policy-form" @submit.prevent="savePolicy">
<div class="panel-heading"><div><h3>{{t('typePolicyTitle')}}</h3><p>{{t('typePolicySub')}}</p></div><Icon name="ShieldCheck" class="muted"/></div>
<div class="builder-tabs" role="group" :aria-label="t('testTypes')"><button v-for="type in testTypes" :key="type.code" type="button" :class="{selected:policyForm?.code===type.code}" :aria-pressed="policyForm?.code===type.code" @click="selectPolicy(type)"><Icon :name="typeIcon(type.code)" :size="19"/>{{typeLabel(type)}}</button></div>
<div v-if="policyError" class="inline-error" role="alert">{{policyError}} <button class="text-button" type="button" @click="loadPolicies">{{t('retryLoad')}}</button></div>
<div v-if="loading" class="loading-panel">{{t('loading')}}</div>
<template v-else-if="policyForm">
<div class="form-grid"><label class="toggle-field span2"><span>{{t('typeActive')}}</span><input v-model="policyForm.active" type="checkbox" class="toggle" v-field-error="{errors:validation.policy,field:'active'}"></label><label><span class="field-label required-field-label">{{t('typeNameId')}}</span><input v-model="policyForm.name" required maxlength="120" v-field-error="{errors:validation.policy,field:'name'}"></label><label><span class="field-label required-field-label">{{t('typeNameEn')}}</span><input v-model="policyForm.name_en" required maxlength="120" v-field-error="{errors:validation.policy,field:'name_en'}"></label><label>{{t('typeDescriptionId')}}<textarea v-model="policyForm.description" rows="3" maxlength="5000" v-field-error="{errors:validation.policy,field:'description'}"></textarea></label><label>{{t('typeDescriptionEn')}}<textarea v-model="policyForm.description_en" rows="3" maxlength="5000" v-field-error="{errors:validation.policy,field:'description_en'}"></textarea></label></div>
<div class="builder-section"><h3>{{t('policySettings')}}</h3><div class="form-grid"><label v-for="key in policyBooleanKeys" :key="key" class="toggle-field"><span>{{t(policyLabels[key])}}</span><input v-model="policyForm[key]" type="checkbox" class="toggle" v-field-error="{errors:validation.policy,field:key}"></label><label v-for="field in policyNumberFields" :key="field.key"><span class="field-label required-field-label">{{t(field.label)}}</span><input v-model.number="policyForm[field.key]" type="number" :min="field.min" :max="field.max" required v-field-error="{errors:validation.policy,field:field.key}"><small v-if="field.key==='attempts_limit'">{{t('zeroUnlimited')}}</small></label><label><span class="field-label required-field-label">{{t('scoringMethod')}}</span><select v-model="policyForm.scoring_method" required v-field-error="{errors:validation.policy,field:'scoring_method'}"><option v-for="method in scoringMethods" :key="method.value" :value="method.value">{{t(method.label)}}</option></select></label></div></div>
<div class="builder-section"><div class="section-heading compact"><div><h3>{{t('levelThresholds')}}</h3><p>{{t('thresholdNote')}}</p></div><button type="button" class="button small secondary" @click="addThreshold(policyForm)"><Icon name="Plus" :size="17"/>{{t('addLevel')}}</button></div><div v-for="(level,index) in policyForm.level_thresholds" :key="index" class="section-builder-card"><div class="form-grid"><label><span class="field-label required-field-label">{{t('levelCode')}}</span><input v-model="level.code" required maxlength="20" placeholder="A1" v-field-error="{errors:validation.policy,field:'level_thresholds.'+index+'.code'}"></label><label><span class="field-label required-field-label">{{t('levelName')}}</span><input v-model="level.name" required maxlength="120" v-field-error="{errors:validation.policy,field:'level_thresholds.'+index+'.name'}"></label><label><span class="field-label required-field-label">{{t('minimumPercent')}}</span><input v-model.number="level.min_score" type="number" min="0" max="100" step="0.01" required v-field-error="{errors:validation.policy,field:'level_thresholds.'+index+'.min_score'}"></label><label>{{t('learningRecommendation')}}<textarea v-model="level.recommendation" rows="2" maxlength="2000" v-field-error="{errors:validation.policy,field:'level_thresholds.'+index+'.recommendation'}"></textarea></label></div><button class="text-button danger-text" type="button" @click="policyForm.level_thresholds.splice(index,1)"><Icon name="Trash2" :size="17"/>{{t('removeLevel')}}</button></div></div>
<p class="muted">{{t('certificationPolicyNote')}}</p><div class="form-footer"><button class="button" :disabled="policyBusy"><Icon name="Check" :size="17"/>{{t('savePolicy')}}</button></div>
</template></form></div></template>
<template v-else><section class="panel admin-table-panel"><div class="list-toolbar"><div class="search-input"><Icon name="Search" :size="18"/><input v-model="search" :placeholder="t('search').replace(/[.\u2026]+$/,'')+'\u2026'" aria-label="Search records"></div><div class="table-filters"><select v-if="['questions','packages'].includes(resource)" v-model="filterTestType" :aria-label="t('testType')"><option value="">{{t('allTypes')}}</option><option v-for="type in testTypes" :key="type.code" :value="type.code">{{typeLabel(type)}}</option></select><template v-if="resource==='questions'"><select v-model="filterCompetency" aria-label="Filter competency"><option value="">All competencies</option><option v-for="c in state.competencies" :value="c.id" :key="c.id">{{c.name}}</option></select><select v-model="filterType" aria-label="Filter question type"><option value="">All types</option><option v-for="q in types" :value="q.code" :key="q.code">{{q.name||human(q.code)}}</option></select><select v-model="filterStatus" aria-label="Filter status"><option value="">All statuses</option><option v-for="s in ['draft','review','active','archived']" :key="s">{{s}}</option></select></template><span class="record-count muted" role="status">{{total}} {{ui('records','data')}}</span><button v-if="hasFilters" type="button" class="text-button clear-filters" @click="clearFilters"><Icon name="FilterX" :size="18"/>{{ui('Clear filters','Hapus filter')}}</button></div></div><div v-if="resource==='questions'&&selectedIds.length" class="bulk-toolbar"><strong>{{selectedIds.length}} selected</strong><label class="sr-only" for="bulk-action">Bulk question action</label><select id="bulk-action" v-model="bulkAction"><option value="draft">Move to draft</option><option value="review">Send for review</option><option value="active">Activate questions</option><option value="archived">Archive questions</option></select><button class="button small" @click="applyBulk" :disabled="busy">Apply to selected</button><button class="text-button" @click="selectedIds=[]">Clear selection</button></div><div v-if="loading" class="loading-panel" role="status" aria-live="polite"><span class="loader" aria-hidden="true"></span>{{t('loading')}}</div><template v-else><p id="admin-table-hint" class="table-scroll-hint"><Icon name="MoveHorizontal" :size="18" aria-hidden="true"/>{{ui('Scroll the table horizontally to see every column and action.','Geser tabel ke samping untuk melihat seluruh kolom dan tindakan.')}}</p><div class="table-scroll" role="region" :aria-label="t(resource)" aria-describedby="admin-table-hint" tabindex="0"><table><caption class="sr-only">{{t(resource)}} ? {{total}} {{ui('records','data')}}</caption><thead><tr><th v-if="resource==='questions'" class="selection-column"><input type="checkbox" :checked="rows.length>0&&rows.every(row=>selectedIds.includes(row.id))" @change="toggleAll" aria-label="Select all questions on this page"></th><th v-for="h in headers" :key="h" scope="col">{{h}}</th><th scope="col">{{t('actions')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td v-if="resource==='questions'" class="selection-column"><input type="checkbox" :checked="selectedIds.includes(row.id)" @change="toggleSelection(row.id)" :aria-label="'Select '+row.title"></td><template v-if="resource==='questions'"><td><span class="row-code">{{row.code}}</span><strong class="row-title">{{row.title}}</strong></td><td>{{row.competency?.name||'—'}}</td><td><span class="badge neutral">{{human(row.type)}}</span></td><td><span class="badge" :class="row.status==='active'?'green':row.status==='draft'?'neutral':'amber'">{{human(row.status)}}</span></td><td>v{{row.version}}</td></template><template v-else-if="resource==='packages'"><td><span class="row-code">{{row.code}}</span><strong class="row-title">{{row.name}}</strong><span class="badge neutral">{{typeLabel(row.test_type||'certification')}}</span></td><td>{{row.sections?.length||0}}</td><td>{{row.duration_minutes}} min</td><td><span class="badge" :class="row.published?'green':'neutral'">{{row.published?t('published'):t('draft')}}</span></td><td><Icon :name="row.certificate_enabled?'BadgeCheck':'Minus'" :size="18" class="muted"/></td></template><template v-else-if="resource==='participants'"><td><span class="table-title"><span class="small-avatar">{{row.name?.[0]}}</span>{{row.name}}</span></td><td>{{row.email}}</td><td>{{row.profile?.country||'—'}}</td><td><span class="badge" :class="row.activation_pending||row.account_status==='pending_activation'?'amber':row.active?'green':'neutral'">{{row.activation_pending||row.account_status==='pending_activation'?ui('Pending activation','Menunggu aktivasi'):row.active?t('active'):t('inactive')}}</span></td><td>{{date(row.created_at)}}</td></template><template v-else-if="resource==='competencies'"><td><span class="table-title"><span class="skill-icon" :style="{'--skill-color':row.color}"><Icon :name="row.icon||'BookOpen'" :size="19"/></span><span><strong class="row-title">{{row.name}}</strong><small>{{row.name_en}}</small></span></span></td><td>{{row.code}}</td><td>{{row.sort_order}}</td><td><span class="badge" :class="row.active?'green':'neutral'">{{row.active?t('active'):t('inactive')}}</span></td></template><template v-else-if="resource==='groups'"><td><strong>{{row.title}}</strong></td><td><span class="badge neutral">{{human(row.kind)}}</span></td><td>{{row.media_asset?.original_name||'—'}}</td></template><template v-else-if="resource==='media'"><td><span class="table-title"><span class="table-file"><Icon :name="row.kind==='audio'?'AudioLines':row.kind==='video'?'Video':'Image'" :size="21"/></span>{{row.original_name}}</span></td><td>{{human(row.kind)}}</td><td>{{(row.size/1024/1024).toFixed(2)}} MB</td><td>{{date(row.created_at)}}</td></template><template v-else-if="resource==='reviews'"><td><strong>{{row.attempt?.user?.name||'Participant'}}</strong><span class="row-code">{{row.attempt?.user?.email}}</span></td><td>{{row.question?.title||row.question_key}}</td><td><span class="badge purple">{{human(row.question?.type)}}</span></td><td class="response-cell">{{typeof row.response==='object'?'Recorded response':row.response}}</td><td><span class="badge amber">{{row.manual_score!==null&&row.manual_score!==undefined?'Reviewed':'Pending'}}</span></td></template><template v-else-if="resource==='certificates'"><td><strong>{{row.number}}</strong></td><td>{{row.payload?.holder_name||row.attempt?.snapshot?.participant_name||'—'}}</td><td>{{row.payload?.total_score??row.score}}</td><td><span class="badge" :class="row.status==='valid'?'green':'red'">{{human(row.status)}}</span></td><td>{{date(row.issued_at)}}</td></template><template v-else-if="resource==='levels'"><td><strong>{{row.name}}</strong></td><td><span class="badge blue">{{row.code}}</span></td><td>{{row.min_score}}</td><td>{{row.sort_order}}</td></template><template v-else-if="resource==='audit'"><td><strong>{{human(row.event)}}</strong></td><td>{{row.user?.name||row.user_id||'System'}}</td><td>{{row.subject_type||'—'}} {{row.subject_id||''}}</td><td>{{date(row.created_at)}}</td></template><td><div class="row-actions"><template v-if="!isReadOnly&&resource!=='media'"><button class="icon-button" @click="open(row)" :aria-label="t('edit')" title="Edit"><Icon name="Pencil" :size="16"/></button><button v-if="resource==='questions'" class="icon-button" @click="showUsage(row)" :aria-label="t('usageHistory')" :title="t('usageHistory')"><Icon name="ScrollText" :size="17"/></button><button v-if="resource==='questions'" class="icon-button" @click="duplicate(row)" :aria-label="t('duplicate')" title="Duplicate"><Icon name="Copy" :size="16"/></button><button v-if="resource!=='levels'" class="icon-button danger-text" @click="archive(row)" :aria-label="resource==='groups'?(state.language==='id'?'Hapus grup':'Delete group'):t('delete')" :title="resource==='groups'?'Delete group':'Archive'"><Icon :name="resource==='groups'?'Trash2':'Archive'" :size="16"/></button></template><a v-if="resource==='media'" :href="'/api/media/'+row.id" target="_blank" rel="noopener" class="icon-button" aria-label="Open media"><Icon name="ExternalLink" :size="17"/></a><button v-if="resource==='reviews'" class="button small secondary" @click="openReview(row)">{{t('review')}}<Icon name="ArrowUpRight" :size="14"/></button><template v-if="resource==='certificates'"><a :href="'/api/certificates/'+row.id+'/pdf'" target="_blank" rel="noopener" class="icon-button" aria-label="Download PDF"><Icon name="Download" :size="17"/></a><button class="icon-button" @click="go('/verify/'+(row.verification_token||row.token))" aria-label="Verify certificate"><Icon name="ShieldCheck" :size="17"/></button><button v-if="row.status!=='revoked'" class="icon-button danger-text" @click="revoke(row)" aria-label="Revoke certificate"><Icon name="ShieldX" :size="17"/></button></template><button v-if="resource==='audit'" class="icon-button" @click="detail=row" aria-label="View event"><Icon name="Eye" :size="17"/></button></div></td></tr></tbody></table></div><div v-if="!rows.length" class="table-empty" role="status"><Icon :name="resource==='reviews'?'ClipboardCheck':'FolderOpen'" :size="32"/><strong>{{hasFilters?ui('No matching records','Tidak ada data yang cocok'):resource==='reviews'?ui('All caught up','Semua penilaian sudah selesai'):t('empty')}}</strong><p>{{emptyDescription}}</p><button v-if="hasFilters" type="button" class="button secondary" @click="clearFilters">{{ui('Clear filters','Hapus filter')}}</button><a v-if="resource==='questions'" href="/api/admin/questions/template" class="text-button">{{t('template')}}<Icon name="Download" :size="15"/></a></div></template><div class="pagination" :aria-label="ui('Table pagination','Halaman tabel')"><span role="status">{{total}} records · Page {{page}} of {{lastPage}}</span><div><button class="button small secondary" :disabled="loading||page<=1" @click="page--;load()"><Icon name="ChevronLeft" :size="16"/>{{t('previous')}}</button><button class="button small secondary" :disabled="loading||page>=lastPage" @click="page++;load()">{{t('next')}}<Icon name="ChevronRight" :size="16"/></button></div></div></section></template>
</div>
<div v-if="modal" class="modal-overlay" :inert="activeDialog!=='editor'?true:undefined" @click.self="modal=false"><form class="modal builder-modal" data-dialog="editor" tabindex="-1" role="dialog" aria-modal="true" :aria-label="t(resource)" @submit.prevent="save"><header class="modal-header"><div><span class="eyebrow">{{form.id?'EDIT RECORD':'CREATE SOMETHING MEANINGFUL'}}</span><h2>{{resource==='questions'?'Question builder':resource==='packages'?'Assessment builder':(form.id?t('edit'):t('create'))+' · '+t(resource)}}</h2></div><button class="icon-button" type="button" @click="modal=false" aria-label="Close"><Icon name="X" :size="21"/></button></header><div class="modal-body"><p class="required-note">{{ui('Fields marked with * are required.','Kolom bertanda * wajib diisi.')}}</p><div v-if="error" class="inline-error" role="alert">{{error}}</div>
<template v-if="resource==='questions'"><div class="builder-tabs"><span class="selected"><Icon name="PenLine" :size="17"/>Question details</span><button type="button" @click="showPreview"><Icon name="Eye" :size="17"/>{{t('preview')}}</button><span v-if="form.id" class="muted">Version {{form.version}} · New versions preserve past results</span></div><div class="form-grid"><label class="span2"><span class="field-label required-field-label">{{t('title')}}</span><input v-model="form.title" required maxlength="255" placeholder="A clear, descriptive title for your question" v-field-error="{errors:validation.editor,field:'title'}"></label><label>{{t('code')}}<input v-model="form.code" maxlength="60" placeholder="Generated automatically if empty" v-field-error="{errors:validation.editor,field:'code'}"></label><label><span class="field-label required-field-label">{{t('competencies')}}</span><select v-model="form.competency_id" required v-field-error="{errors:validation.editor,field:'competency_id'}"><option v-for="c in state.competencies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{t('type')}}<select v-model="form.type" @change="typeChange" v-field-error="{errors:validation.editor,field:'type'}"><option v-for="q in types" :key="q.code" :value="q.code">{{q.name||human(q.code)}}</option></select></label><label>Shared passage / media group<select v-model="form.question_group_id" v-field-error="{errors:validation.editor,field:'question_group_id'}"><option :value="null">No shared group</option><option v-for="g in groups" :key="g.id" :value="g.id">{{g.title}} · {{g.kind}}</option></select></label><label>{{t('difficulty')}}<select v-model="form.difficulty" v-field-error="{errors:validation.editor,field:'difficulty'}"><option v-for="d in ['easy','medium','hard','beginner','intermediate','advanced']" :value="d" :key="d">{{human(d)}}</option></select></label><label>{{t('status')}}<select v-model="form.status" v-field-error="{errors:validation.editor,field:'status'}"><option v-for="s in ['draft','review','active','archived']" :value="s" :key="s">{{human(s)}}</option></select></label><label><span class="field-label required-field-label">{{t('weight')}}</span><input v-model.number="form.weight" type="number" min="0.01" max="1000" step="0.01" required v-field-error="{errors:validation.editor,field:'weight'}"></label><label>Question time limit (seconds; empty = no limit)<input v-model.number="form.duration_seconds" type="number" min="1" max="7200" v-field-error="{errors:validation.editor,field:'duration_seconds'}"></label><label class="span2">{{t('instructions')}}<textarea v-model="form.instructions" rows="2" placeholder="What should the participant do?" v-field-error="{errors:validation.editor,field:'instructions'}"></textarea></label><label class="span2">{{t('prompt')}}<RichEditor v-model="form.prompt" placeholder="Write the question, conversation, or task…" v-field-error="{errors:validation.editor,field:'prompt'}"/></label></div>
<div class="builder-section"><div class="section-heading compact"><div><h3>{{t('questionConfidentiality')}}</h3><p>{{t('allowedTypesHelp')}}</p></div><button v-if="form.id" class="button small secondary" type="button" @click="showUsage(form)"><Icon name="ScrollText" :size="17"/>{{t('usageHistory')}}</button></div><fieldset><legend>{{t('allowedTestTypes')}}</legend><div class="form-grid"><label v-for="type in testTypes" :key="type.code" class="checkbox-label"><input v-model="form.allowed_test_types" type="checkbox" :value="type.code" :disabled="form.confidential&&type.code!=='certification'" v-field-error="{errors:validation.editor,field:'allowed_test_types'}"><span>{{typeLabel(type)}}</span></label></div></fieldset><div class="form-grid"><label class="toggle-field span2"><span>{{t('confidentialQuestion')}}<small>{{t('confidentialHelp')}}</small></span><input v-model="form.confidential" type="checkbox" class="toggle" @change="confidentialChanged" v-field-error="{errors:validation.editor,field:'confidential'}"></label><label>{{t('usageLimit')}}<input v-model.number="form.usage_limit" type="number" min="1" max="10000000" v-field-error="{errors:validation.editor,field:'usage_limit'}"></label><div v-if="form.id"><strong>{{t('usedCount')}}</strong><p>{{form.usage_count??form.uses_count??0}}</p></div></div></div>
<div v-if="['dropdown','fill_blank'].includes(form.type)" class="builder-section"><div class="section-heading compact"><div><h3>Multiple blanks</h3><p>Use [blank ID] in your question text to indicate each position.</p></div><button type="button" class="button small secondary" @click="addBlank"><Icon name="Plus" :size="16"/>Add blank</button></div><div v-for="(blank,bi) in form.metadata.blanks||[]" :key="blank.id" class="section-builder-card"><div class="section-card-header"><strong>Blank {{bi+1}} ? [{{blank.id}}]</strong><button class="icon-button danger-text" type="button" @click="form.metadata.blanks.splice(bi,1)" aria-label="Remove blank"><Icon name="Trash2" :size="17"/></button></div><div class="form-grid"><label><span class="field-label required-field-label">Blank label</span><input v-model="blank.label" required v-field-error="{errors:validation.editor,field:'metadata.blanks.'+bi+'.label'}"></label><label v-if="form.type==='fill_blank'"><span class="field-label required-field-label">Correct answer</span><input v-model="blank.correct" required v-field-error="{errors:validation.editor,field:'answer_schema.correct.'+blank.id}"></label><label v-else><span class="field-label required-field-label">Correct option</span><select v-model="blank.correct" required v-field-error="{errors:validation.editor,field:'answer_schema.correct.'+blank.id}"><option value="">Choose correct option</option><option v-for="opt in blank.options||[]" :key="opt.id" :value="opt.id">{{opt.text||opt.id}}</option></select></label></div><template v-if="form.type==='dropdown'"><div v-for="(option,oi) in blank.options||[]" :key="option.id" class="option-builder-row"><span class="choice-letter">{{oi+1}}</span><input v-model="option.text" required placeholder="Choice text" v-field-error="{errors:validation.editor,field:'metadata.blanks.'+bi+'.options.'+oi+'.text'}"><button type="button" class="icon-button" @click="blank.options.splice(oi,1)" aria-label="Remove choice"><Icon name="X" :size="16"/></button></div><button class="text-button" type="button" @click="blank.options.push({id:'o'+Date.now(),text:''})"><Icon name="Plus" :size="15"/>Add choice</button></template></div></div><div v-if="hasOptions" class="builder-section"><div class="section-heading compact"><div><h3>{{isOrdering?'Items in the correct order':['matching','drag_drop'].includes(form.type)?'Matching pairs':t('options')}}</h3><p>{{isOrdering?'Arrange the source items here. Their order is the answer key.':['matching','drag_drop'].includes(form.type)?'Connect every left item to its correct right item.':'Select the correct response beside each option.'}}</p></div><button type="button" class="button small secondary" @click="addOption"><Icon name="Plus" :size="16"/>{{t('addOption')}}</button></div><div class="option-builder-row" v-for="(option,i) in form.options" :key="option.id"><span class="choice-letter">{{String.fromCharCode(65+i)}}</span><input v-model="option.text" :placeholder="'Option '+(i+1)" required maxlength="5000" v-field-error="{errors:validation.editor,field:(['matching','drag_drop'].includes(form.type)?'metadata.left_items.':'options.')+i+'.text'}"><template v-if="['matching','drag_drop'].includes(form.type)"><Icon name="ArrowRight" :size="16"/><select v-model="option.match_id" required v-field-error="{errors:validation.editor,field:'answer_schema.correct.'+option.id}"><option value="">Match to…</option><option v-for="match in form.metadata.matches" :key="match.id" :value="match.id">{{match.text}}</option></select></template><label v-else-if="!isOrdering" class="correct-option"><input :type="form.type==='multiple_response'?'checkbox':'radio'" name="correct-answer" :checked="isCorrect(option.id)" @change="setCorrect(option.id)"><span>Correct</span></label><button type="button" class="icon-button danger-text" @click="form.options.splice(i,1)" aria-label="Remove option"><Icon name="X" :size="17"/></button></div><template v-if="['matching','drag_drop'].includes(form.type)"><h4>Right hand choices</h4><div v-for="(match,i) in form.metadata.matches" :key="match.id" class="option-builder-row"><span class="choice-letter">{{i+1}}</span><input v-model="match.text" required placeholder="Matching target" v-field-error="{errors:validation.editor,field:'options.'+i+'.text'}"><button type="button" class="icon-button" @click="form.metadata.matches.splice(i,1)" aria-label="Remove matching target"><Icon name="X" :size="17"/></button></div><button type="button" class="text-button" @click="form.metadata.matches.push({id:'m'+Date.now(),text:''})"><Icon name="Plus" :size="16"/>Add matching target</button></template></div>
<div v-else-if="form.type==='true_false'" class="builder-section"><h3>{{t('correct')}}</h3><div class="form-grid"><label class="radio-card"><input type="radio" value="true" v-model="form.answer_schema.correct" v-field-error="{errors:validation.editor,field:'answer_schema.correct'}">True / Benar</label><label class="radio-card"><input type="radio" value="false" v-model="form.answer_schema.correct" v-field-error="{errors:validation.editor,field:'answer_schema.correct'}">False / Salah</label></div></div>
<div v-else-if="['short_answer','fill_blank'].includes(form.type)&&!form.metadata.blanks?.length" class="builder-section"><h3>Accepted answers</h3><div class="form-grid"><label>Primary answer<input v-model="form.answer_schema.correct" placeholder="The preferred correct answer" v-field-error="{errors:validation.editor,field:'answer_schema.correct'}"></label><label>Alternative accepted answers<textarea v-model="form.accepted_text" rows="3" placeholder="One alternative per line" v-field-error="{errors:validation.editor,field:'answer_schema.accepted'}"></textarea></label></div></div>
<div v-if="['essay','speaking'].includes(form.type)" class="builder-section"><div class="section-heading compact"><div><h3>Assessment rubric</h3><p>Help reviewers give consistent, useful feedback.</p></div><button type="button" class="button small secondary" @click="form.metadata.rubric.push({name:'',description:'',weight:1})"><Icon name="Plus" :size="16"/>Add criterion</button></div><div v-for="(criterion,i) in form.metadata.rubric" :key="i" class="rubric-builder-row"><label><span class="field-label required-field-label">Criterion</span><input v-model="criterion.name" required placeholder="e.g. Fluency" v-field-error="{errors:validation.editor,field:'metadata.rubric.'+i+'.name'}"></label><label>Descriptor<input v-model="criterion.description" placeholder="What does a strong response demonstrate?" v-field-error="{errors:validation.editor,field:'metadata.rubric.'+i+'.description'}"></label><label>Weight<input type="number" v-model.number="criterion.weight" min="0.01" step="0.01" v-field-error="{errors:validation.editor,field:'metadata.rubric.'+i+'.weight'}"></label><button type="button" class="icon-button" @click="form.metadata.rubric.splice(i,1)" aria-label="Remove criterion"><Icon name="X" :size="17"/></button></div><div v-if="form.type==='speaking'" class="form-grid"><label>Preparation time (seconds)<input v-model.number="form.metadata.preparation_seconds" type="number" min="0" max="300" v-field-error="{errors:validation.editor,field:'metadata.preparation_seconds'}"></label><label>Recording time (seconds)<input v-model.number="form.metadata.recording_seconds" type="number" min="5" max="3600" v-field-error="{errors:validation.editor,field:'metadata.recording_seconds'}"></label><label>Maximum recording attempts<input v-model.number="form.metadata.max_recordings" type="number" min="1" max="10" v-field-error="{errors:validation.editor,field:'metadata.max_recordings'}"></label></div><div v-else class="form-grid"><label>Suggested minimum words<input v-model.number="form.metadata.min_words" type="number" min="0" max="5000" v-field-error="{errors:validation.editor,field:'metadata.min_words'}"></label><label>Maximum characters<input v-model.number="form.metadata.max_length" type="number" min="100" max="50000" v-field-error="{errors:validation.editor,field:'metadata.max_length'}"></label></div></div>
<div v-if="['listening','image','video','conversation'].includes(form.type)" class="builder-section"><h3>Question media</h3><div class="form-grid"><label>Media file<select v-model="form.metadata.media_asset_id" v-field-error="{errors:validation.editor,field:'metadata.media_asset_id'}"><option :value="null">Choose a media asset</option><option v-for="asset in media" :key="asset.id" :value="asset.id">{{asset.original_name}} · {{asset.kind}}</option></select></label><label>Media kind<select v-model="form.metadata.media_kind" v-field-error="{errors:validation.editor,field:'metadata.media_kind'}"><option value="audio">Audio</option><option value="image">Image</option><option value="video">Video</option></select></label><label v-if="form.type==='listening'">Maximum audio plays (0 = unlimited)<input v-model.number="form.metadata.max_plays" type="number" min="0" max="20" v-field-error="{errors:validation.editor,field:'metadata.max_plays'}"></label></div></div>
<div class="builder-section"><div class="form-grid"><label v-if="!['essay','speaking'].includes(form.type)" class="checkbox-label span2"><input type="checkbox" v-model="form.metadata.manual" v-field-error="{errors:validation.editor,field:'metadata.manual'}"><span>Require a human reviewer for this question</span></label><label class="span2">Answer explanation<textarea v-model="form.explanation" rows="3" placeholder="Explain why the answer is correct. Stored for internal review." v-field-error="{errors:validation.editor,field:'explanation'}"></textarea></label><label v-if="['multiple_response','matching','drag_drop','sentence_ordering','word_ordering'].includes(form.type)" class="checkbox-label"><input type="checkbox" v-model="form.answer_schema.partial_credit" v-field-error="{errors:validation.editor,field:'answer_schema.partial_credit'}"><span>Allow partial credit for partially correct responses</span></label></div></div><details v-if="form.versions?.length" class="version-history"><summary>Question version history</summary><p v-for="version in form.versions" :key="version.id">Version {{version.version}} · {{date(version.created_at)}}</p></details></template>
<template v-else-if="resource==='packages'"><div class="form-grid"><label class="span2"><span class="field-label required-field-label">{{t('testType')}}</span><select v-model="form.test_type" required @change="packageTypeChanged" v-field-error="{errors:validation.editor,field:'test_type'}"><option v-for="type in testTypes" :key="type.code" :value="type.code">{{typeLabel(type)}}{{type.active===false?' / '+t('inactive'):''}}</option></select><small>{{t('packageTypeHelp')}}</small></label><label><span class="field-label required-field-label">{{t('code')}}</span><input v-model="form.code" required maxlength="60" placeholder="e.g. INBAF-COMPREHENSIVE" v-field-error="{errors:validation.editor,field:'code'}"></label><label><span class="field-label required-field-label">Assessment name</span><input v-model="form.name" required maxlength="255" v-field-error="{errors:validation.editor,field:'name'}"></label><label class="span2">{{t('description')}}<textarea v-model="form.description" rows="3" v-field-error="{errors:validation.editor,field:'description'}"></textarea></label><label><span class="field-label required-field-label">Total duration (minutes)</span><input v-model.number="form.duration_minutes" type="number" required min="1" max="1440" v-field-error="{errors:validation.editor,field:'duration_minutes'}"></label><label><span class="field-label required-field-label">Passing score (percentage)</span><input v-model.number="form.pass_score" type="number" required min="0" max="100" step="0.01" v-field-error="{errors:validation.editor,field:'pass_score'}"></label><label>Question selection<select v-model="form.question_selection" v-field-error="{errors:validation.editor,field:'question_selection'}"><option value="random">Random from active question bank</option><option value="manual">Select questions manually</option></select></label><label>Available from<input v-model="form.settings.starts_at" type="datetime-local" v-field-error="{errors:validation.editor,field:'settings.starts_at'}"></label><label>Available until<input v-model="form.settings.ends_at" type="datetime-local" v-field-error="{errors:validation.editor,field:'settings.ends_at'}"></label><label>Access code (optional)<input v-model="form.settings.access_code" autocomplete="off" v-field-error="{errors:validation.editor,field:'settings.access_code'}"></label><label class="toggle-field"><span>{{t('published')}}</span><input type="checkbox" v-model="form.published" class="toggle" v-field-error="{errors:validation.editor,field:'published'}"></label><label v-if="form.test_type==='certification'" class="checkbox-label"><input type="checkbox" v-model="form.certificate_enabled" v-field-error="{errors:validation.editor,field:'certificate_enabled'}"><span>{{t('issueCertificate')}}</span></label><p v-else class="muted">{{t('noOfficialCertificate')}}</p></div><div class="builder-section"><h3>{{t('packageOverrides')}}</h3><p>{{t('overrideHelp')}}</p><div class="form-grid"><label v-for="key in policyBooleanKeys" :key="key">{{t(policyLabels[key])}}<select v-model="form.policy_overrides[key]" v-field-error="{errors:validation.editor,field:'policy_overrides.'+key}"><option :value="null">{{t('inheritTypePolicy')}} ({{policyValue(key)?t('enabled'):t('disabled')}})</option><option :value="true">{{t('enabled')}}</option><option :value="false">{{t('disabled')}}</option></select></label><label v-for="field in policyNumberFields" :key="field.key">{{t(field.label)}}<input v-model.number="form.policy_overrides[field.key]" type="number" :min="field.min" :max="field.max" :placeholder="String(policyValue(field.key))" v-field-error="{errors:validation.editor,field:'policy_overrides.'+field.key}"><small>{{t('inheritedValue')}}: {{policyValue(field.key)}}<template v-if="field.key==='attempts_limit'"> ? {{t('zeroUnlimited')}}</template></small></label><label class="span2">{{t('scoringMethod')}}<select v-model="form.policy_overrides.scoring_method" v-field-error="{errors:validation.editor,field:'policy_overrides.scoring_method'}"><option :value="null">{{t('inheritTypePolicy')}} ({{t(scoringMethods.find(method=>method.value===policyValue('scoring_method'))?.label||'weightedScoring')}})</option><option v-for="method in scoringMethods" :key="method.value" :value="method.value">{{t(method.label)}}</option></select></label><label class="checkbox-label span2"><input type="checkbox" :checked="Array.isArray(form.policy_overrides.level_thresholds)" @change="toggleOverrideLevels"><span>{{t('overrideThresholds')}}</span></label></div><template v-if="Array.isArray(form.policy_overrides.level_thresholds)"><p>{{t('thresholdNote')}}</p><div v-for="(level,index) in form.policy_overrides.level_thresholds" :key="index" class="section-builder-card"><div class="form-grid"><label><span class="field-label required-field-label">{{t('levelCode')}}</span><input v-model="level.code" required maxlength="20" v-field-error="{errors:validation.editor,field:'policy_overrides.level_thresholds.'+index+'.code'}"></label><label><span class="field-label required-field-label">{{t('levelName')}}</span><input v-model="level.name" required maxlength="120" v-field-error="{errors:validation.editor,field:'policy_overrides.level_thresholds.'+index+'.name'}"></label><label><span class="field-label required-field-label">{{t('minimumPercent')}}</span><input v-model.number="level.min_score" type="number" min="0" max="100" step="0.01" required v-field-error="{errors:validation.editor,field:'policy_overrides.level_thresholds.'+index+'.min_score'}"></label><label>{{t('learningRecommendation')}}<textarea v-model="level.recommendation" rows="2" maxlength="2000" v-field-error="{errors:validation.editor,field:'policy_overrides.level_thresholds.'+index+'.recommendation'}"></textarea></label></div><button class="text-button danger-text" type="button" @click="form.policy_overrides.level_thresholds.splice(index,1)"><Icon name="Trash2" :size="17"/>{{t('removeLevel')}}</button></div><button type="button" class="button small secondary" @click="addThreshold(form.policy_overrides)"><Icon name="Plus" :size="17"/>{{t('addLevel')}}</button></template></div><div class="builder-section" v-field-error="{errors:validation.editor,field:'sections'}"><div class="section-heading compact"><div><h3>Assessment sections</h3><p>Drag sections to reorder. Weights are normalized in the final score.</p></div><button class="button small secondary" type="button" @click="addSection"><Icon name="Plus" :size="17"/>{{t('addSection')}}</button></div><div v-for="(section,i) in form.sections" :key="i" class="section-builder-card" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="dropSection(i)"><div class="section-card-header"><Icon name="GripVertical" :size="19"/><strong>{{t('section')}} {{i+1}}</strong><button type="button" class="icon-button" @click="moveSection(i,-1)" :disabled="i===0" aria-label="Move section up"><Icon name="ChevronUp" :size="18"/></button><button type="button" class="icon-button" @click="moveSection(i,1)" :disabled="i===form.sections.length-1" aria-label="Move section down"><Icon name="ChevronDown" :size="18"/></button><button type="button" class="icon-button danger-text" @click="form.sections.splice(i,1)" aria-label="Remove section"><Icon name="Trash2" :size="17"/></button></div><div class="form-grid"><label><span class="field-label required-field-label">Section name</span><input v-model="section.title" required maxlength="255" v-field-error="{errors:validation.editor,field:'sections.'+i+'.title'}"></label><label><span class="field-label required-field-label">{{t('competencies')}}</span><select v-model="section.competency_id" required @change="sectionEligibilityChanged(section)" v-field-error="{errors:validation.editor,field:'sections.'+i+'.competency_id'}"><option v-for="c in state.competencies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label><span class="field-label required-field-label">Duration (minutes)</span><input v-model.number="section.duration_minutes" type="number" min="1" required v-field-error="{errors:validation.editor,field:'sections.'+i+'.duration_minutes'}"></label><label><span class="field-label required-field-label">{{t('weight')}}</span><input v-model.number="section.weight" type="number" min="0.01" step="0.01" required v-field-error="{errors:validation.editor,field:'sections.'+i+'.weight'}"></label><label><span class="field-label required-field-label">Question count</span><input v-model.number="section.question_count" type="number" min="1" max="500" required :disabled="form.question_selection==='manual'" v-field-error="{errors:validation.editor,field:'sections.'+i+'.question_count'}"></label><label class="checkbox-label"><input v-model="section.randomize" type="checkbox" v-field-error="{errors:validation.editor,field:'sections.'+i+'.randomize'}"><span>Randomize question order</span></label><fieldset class="span2"><legend>{{t('difficultySelection')}}</legend><div class="form-grid"><label v-for="difficulty in ['easy','medium','hard','beginner','intermediate','advanced']" :key="difficulty" class="checkbox-label"><input v-model="section.difficulties" type="checkbox" :value="difficulty" @change="sectionEligibilityChanged(section)" v-field-error="{errors:validation.editor,field:'sections.'+i+'.difficulties'}"><span>{{human(difficulty)}}</span></label></div><small>{{t('difficultySelectionHelp')}}</small></fieldset></div><div v-if="form.question_selection==='manual'" class="question-selector"><h4>Select active questions · {{section.question_ids.length}} selected</h4><label v-for="q in sectionQuestions(section)" :key="q.id" class="checkbox-label"><input type="checkbox" :checked="section.question_ids.includes(q.id)" @change="selectQuestion(section,q.id)"><span><strong>{{q.title}}</strong><small>{{q.code}} · {{human(q.type)}}</small></span></label><p v-if="!sectionQuestions(section).length" class="muted">{{t('noEligibleQuestions')}}</p></div></div><div v-if="!form.sections.length" class="empty-small">Add your first section to start shaping this assessment.</div><div class="builder-summary"><span><Icon name="Clock3" :size="17"/>Section duration: {{form.sections.reduce((n,s)=>n+Number(s.duration_minutes||0),0)}} / {{form.duration_minutes}} min</span><span>{{form.sections.reduce((n,s)=>n+Number(s.question_count||0),0)}} questions</span></div></div></template>
